//! The in-page JavaScript, generated by `scripts/browser-assets.ts` from the
//! pinned playwright-core 1.63.0 (Apache-2.0, see `assets/PLAYWRIGHT-LICENSE`
//! and `assets/PLAYWRIGHT-NOTICE`) and the TS node's own helpers;
//! `bun run browser-assets:check` fails when they are stale.
//!
//! Layout: implemented here.

/// Playwright's injected script. Evaluate as
/// `(() => { const module = {}; <INJECTED>; return new (module.exports.InjectedScript())(globalThis, <options>); })()`.
pub const INJECTED: &str = include_str!("assets/injected.js");

/// Playwright's main-world WebSocket mock (`routeWebSocket`); defines
/// `module.exports.inject`.
pub const WEBSOCKET_MOCK: &str = include_str!("assets/websocket-mock.js");

/// `pageMarkdown` (`node/browser-extract.ts`): a function's source.
pub const PAGE_MARKDOWN: &str = include_str!("assets/page-markdown.js");

/// `passwordValues` (`node/browser-extract.ts`): a function's source.
pub const PASSWORD_VALUES: &str = include_str!("assets/password-values.js");

/// `sensitiveField` (`node/browser.ts`): a function's source.
pub const SENSITIVE_FIELD: &str = include_str!("assets/sensitive-field.js");
